using Lastlight.Core;
using System.Text.Json;
public static class PhysicalAcceptance
{
 public static void Run(Definitions d,string output,string assets)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Command(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,r.Message);}long Spawn(World w,string id,int x,int y,int z=0,int n=1){w.CellAt(x,y,z).TerrainId="soil";var r=w.Apply(new(CommandKind.Spawn,DefinitionId:id,X:x,Y:y,Z:z,Quantity:n),d);Require(r.Accepted,r.Message);return r.EntityId;}
  World Fixture(){var w=VerticalWorldGenerator.Create(d,193);w.EnablePhysical(d);w.Physical.Water.Clear();w.Physical.InjectedWater=0;foreach(var p in w.Colony.People.Values)p.Drafted=true;return w;}
  void Save(string name,World w,int z=0){w.Validate(d);SaveStore.Write(Path.Combine(output,name+".lastlight"),w,new ViewState{CameraX=name.Contains("flood")?24:name.Contains("pump")?21:name.Contains("outage")||name.Contains("short")?29:name.Contains("fire")?35:name.Contains("network")?26:64,CameraY=name.Contains("flood")||name.Contains("pump")||name.Contains("network")?21:name.Contains("outage")||name.Contains("short")?30:name.Contains("fire")?35:64,Level=z,OpenTab="Engineering"},d);}
  void Until(World w,Func<bool> done,int limit,string label){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),label+" stalled: "+string.Join(" / ",w.Autonomy.Jobs.Select(j=>j.Kind+":"+j.Work)));w.Validate(d);}
  var demo=PhysicalWorldGenerator.Create(d,74219);Save("physical-depth",demo);Console.WriteLine("PASS F scenario: authored engineering yard, finite cistern and compatible vertical-slice colony");
  var water=Fixture();for(int y=20;y<=22;y++)for(int x=20;x<=27;x++)water.CellAt(x,y,0).TerrainId=y==21?"soil":"stone";water.CellAt(19,21,0).TerrainId="stone";water.CellAt(28,21,0).TerrainId="stone";
  long gate=Spawn(water,"f-floodgate",24,21);water.AddWater(water.Index(20,21),7,.5,d);water.AddWater(water.Index(21,21),7,0,d);water.AddWater(water.Index(22,21),7,0,d);double initial=water.Physical.InjectedWater;Steps(water,900);Require(water.WaterDepth(water.Index(25,21))==0,"Closed floodgate leaked.");Command(water,new(CommandKind.PhysicalAction,gate,Text:"gate"));Steps(water,900);Require(water.WaterDepth(water.Index(25,21))>0,"Open floodgate did not release water.");Require(water.Physical.Water.Values.Sum(f=>f.Depth)==initial,"Flow lost water.");Save("flood-channel-open",water);Console.WriteLine("PASS F01: bounded conservative mixing, contaminant ledger, closed/open gate response");
  var pump=Fixture();for(int y=20;y<=22;y++)for(int x=20;x<=24;x++)pump.CellAt(x,y,0).TerrainId="stone";pump.CellAt(20,21,0).TerrainId="soil";pump.CellAt(22,21,0).TerrainId="soil";long pumpId=Spawn(pump,"f-pump",21,21);long generator=Spawn(pump,"f-solar",21,20);pump.AddWater(pump.Index(20,21),7,.4,d);Steps(pump,600);Require(pump.WaterDepth(pump.Index(22,21))==0,"Unpowered pump transferred water.");pump.Physical.Devices[generator].Enabled=false;long fueled=Spawn(pump,"generator",18,19);pump.Physical.Devices[fueled].Fuel=30;Spawn(pump,"conduit",20,20);Steps(pump,600);Require(pump.WaterDepth(pump.Index(22,21))>0,"Powered pump failed rated transfer.");Save("powered-pump",pump);Console.WriteLine("PASS F01/F03: pump requires connected supply, rated transfer and conserved contamination");
  var outage=Fixture();long lamp=Spawn(outage,"sunlamp",30,30);generator=Spawn(outage,"generator",27,30);long conduit=Spawn(outage,"conduit",29,30);outage.Physical.Devices[generator].Fuel=20;Steps(outage,300);Require(outage.DevicePowered(lamp),"Connected lamp not supplied.");Command(outage,new(CommandKind.PhysicalAction,generator,Text:"toggle"));Steps(outage,300);Require(!outage.DevicePowered(lamp)&&outage.Physical.Networks.Any(n=>n.Cause=="Generation/storage below demand"),"Outage lacks inspectable cause.");Save("electrical-outage",outage);Command(outage,new(CommandKind.PhysicalAction,generator,Text:"toggle"));Steps(outage,300);Require(outage.DevicePowered(lamp),"Restored supply did not recover light.");
  outage.AddWater(outage.Index(29,30),7,0,d);Steps(outage,300);Require(outage.Physical.Devices[conduit].Fault,"Wet conduit did not short.");Save("wet-short",outage);Console.WriteLine("PASS F03: electrical graph, supply outage/restoration, visible causes and wet short");
  var network=Fixture();long wheel=Spawn(network,"f-wheel",20,20);Spawn(network,"f-shaft",21,20);long mill=Spawn(network,"f-mill",22,20);Steps(network,300);Require(!network.DevicePowered(mill),"Dry waterwheel powered mill.");for(int y=18;y<=20;y++)for(int x=19;x<=21;x++)if(!(y==20&&(x==20||x==21)))network.CellAt(x,y,0).TerrainId="stone";network.CellAt(20,19,0).TerrainId="soil";network.AddWater(network.Index(20,19),7,0,d);Steps(network,300);Require(network.DevicePowered(mill),"Wet wheel did not drive mechanical shaft/mill.");long source=Spawn(network,"f-resonator",30,20);Spawn(network,"f-channel",31,20);long ward=Spawn(network,"f-ward",32,20);Steps(network,300);Require(network.DevicePowered(ward),"Thaumic channel did not supply ward.");Spawn(network,"circle",33,20);Steps(network,300);Require(network.Physical.Networks.Any(n=>n.Kind=="Thaumic"&&n.Cause=="Resonance overload")&&network.Physical.Devices[source].Condition<100,"Thaumic overload failed to degrade source stability.");Save("three-network-types",network);Console.WriteLine("PASS F03: distinct waterwheel work, electricity/storage and resonance overload graphs");
  var fire=Fixture();long timber=Spawn(fire,"wood",35,35,n:10);long basalt=Spawn(fire,"column",36,35);Command(fire,new(CommandKind.PhysicalAction,timber,Text:"ignite"));Steps(fire,3000);Require(fire.Find(timber)!.Quantity<10&&fire.Find(basalt)!=null&&fire.Physical.Rooms.Values.Any(r=>r.Smoke>0),"Fire did not consume fuel, spare basalt or generate smoke.");Save("fire-response",fire);long firefighter=fire.Colony.People.Keys.First();Command(fire,new(CommandKind.Draft,firefighter,Quantity:0));fire.Find(firefighter)!.X=34;fire.Find(firefighter)!.Y=35;fire.Colony.People[firefighter].Priorities[0]=1;Until(fire,()=>fire.Physical.Fires.Count==0,9000,"firefight");Require(fire.Physical.Extinguished>0,"Firefight response not recorded.");Console.WriteLine("PASS F02/F04: combustible fuel consumed, basalt survives, heat/smoke and autonomous firefighting");
  var crops=Fixture();crops.Slice.Links.ForEach(l=>l.Enabled=true);for(int x=66;x<=68;x++){crops.CellAt(x,59,1).TerrainId="floor";crops.Slice.BridgeFloors.Add(crops.Index(x,59,1));}int garden=crops.Index(60,64,2);crops.Autonomy.Crops[garden]=new(){Cell=garden,OutputId="grain"};long deepLamp=Spawn(crops,"sunlamp",60,63,2);long deepGen=Spawn(crops,"generator",57,63,2);Spawn(crops,"conduit",59,63,2);crops.Physical.Devices[deepGen].Fuel=50;Steps(crops,300);Require(crops.CropFailure(crops.Autonomy.Crops[garden])=="Too cold","Cold crop reason missing.");Steps(crops,3000);Require(crops.Physical.HarvestFailures>0,"Prolonged cold did not fail crop.");Save("cold-harvest-failure",crops,2);long heater=Spawn(crops,"f-heater",60,62,2);crops.Physical.Devices[deepGen].Fuel=500;crops.AddWater(crops.Index(59,64,2),1,0,d);Steps(crops,6000);crops.Autonomy.Crops[garden]=new(){Cell=garden,OutputId="grain",PlantedAt=crops.Tick};Require(crops.CropFailure(crops.Autonomy.Crops[garden])=="","Heater/irrigation/lamp did not recover viable climate: "+crops.CropFailure(crops.Autonomy.Crops[garden]));Save("garden-climate-recovered",crops,2);Console.WriteLine("PASS F02/F05 EXIT: cold harvest failure has a reason; connected heater/light and irrigation restore viable growth");
  ManufacturingAndAnimals(d,output);
  string fixture=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(assets))!,"../../../tests/fixtures/vertical-slice-day-ten.lastlight");var raw=JsonSerializer.Deserialize<SaveEnvelope>(File.ReadAllText(fixture),JsonFormat.Options)!;Require(raw.FormatVersion==5,"E fixture changed.");var old=SaveStore.Read(fixture,d).World;Require(!old.Physical.Enabled&&old.Levels==3,"E migration enabled hazards or changed map.");Save("stage-e-migrated",old);Console.WriteLine("PASS F migration: authentic format-5 E colony migrates with physical hazards disabled");
  var copy=SaveStore.Read(Path.Combine(output,"garden-climate-recovered.lastlight"),d).World;Steps(crops,900);Steps(copy,900);Require(SaveStore.Fingerprint(crops)==SaveStore.Fingerprint(copy),"Physical reload continuation diverged.");var bad=Fixture();bad.Physical.Water[0]=new(){Depth=8};bool rejected=false;try{bad.Validate(d);}catch(InvalidDataException){rejected=true;}Require(rejected,"Invalid fluid accepted.");Console.WriteLine("PASS F integrity: conservative ledgers, bounded fields and deterministic saved continuation");
 }
 private static void ManufacturingAndAnimals(Definitions d,string output)
 {
  var w=PhysicalWorldGenerator.Create(d,74219);void Require(bool v,string m){if(!v)throw new Exception(m);}void Command(WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,r.Message);}void Until(Func<bool> done,int max,string name){for(int i=0;i<max&&!done();i++)w.Step(d);Require(done(),name+" stalled");w.Validate(d);}
  foreach(var p in w.Colony.People.Values){p.Drafted=false;Array.Fill(p.Schedule,ScheduleActivity.Work);}long maker=w.Colony.People.Keys.First();w.Colony.People[maker].Skills[11]=15;
  var smelter=w.Entities.First(e=>e.DefinitionId=="f-smelter");var gen=w.Entities.First(e=>e.DefinitionId=="generator");var kiln=w.Entities.First(e=>e.DefinitionId=="f-kiln");Command(new(CommandKind.PhysicalAction,kiln.Id,Text:"toggle"));w.Physical.Devices[gen.Id].Fuel=100;
  Command(new(CommandKind.EditBill,smelter.Id,"f-smelt",Text:"add"));Until(()=>w.Resources("f-ingot").Total>=2,20000,"ore to ingot");
  var bench=w.Entities.FirstOrDefault(e=>e.DefinitionId=="workbench");if(bench==null){var r=w.Apply(new(CommandKind.Spawn,DefinitionId:"workbench",X:52,Y:66),d);Require(r.Accepted,r.Message);bench=w.Find(r.EntityId)!;}int parts=w.Resources("f-parts").Total;Command(new(CommandKind.EditBill,bench.Id,"f-make-parts",Text:"add"));Command(new(CommandKind.EditBill,w.Autonomy.Bills.Last(b=>b.BenchId==bench.Id).Id,Quantity:parts+3,Text:"target"));Until(()=>w.Resources("f-parts").Total>parts,20000,"ingot to parts");Require(w.Physical.Crafts.Any(c=>c.Recipe=="f-make-parts"&&c.Maker>0&&c.Quality>0),"Maker/quality provenance absent");
  var loom=w.Entities.First(e=>e.DefinitionId=="f-loom");Command(new(CommandKind.EditBill,loom.Id,"f-make-cloth",Text:"add"));Until(()=>w.Resources("f-cloth").Total>=2,20000,"fiber to cloth");
  gen.Forbidden=false;w.Physical.Devices[gen.Id].Fault=true;Until(()=>w.Physical.Repairs>0,15000,"parts repair");Require(!w.Physical.Devices[gen.Id].Fault,"Physical repair did not resolve fault.");Console.WriteLine("PASS F04: ore/ingot/parts and fiber/cloth through transported bills; maker-quality provenance; parts-consuming repair");
  long grazer=w.Physical.Animals.Keys.First();var animal=w.Find(grazer)!;animal.X=55;animal.Y=67;Command(new(CommandKind.PhysicalAction,grazer,Text:"tame"));Until(()=>w.Physical.Animals[grazer].Tame,24000,"taming with grain");Command(new(CommandKind.PhysicalAction,grazer,Text:"train"));Until(()=>w.Physical.Animals[grazer].Training==1,12000,"training");w.Physical.Animals[grazer].NextProduct=w.Tick;Command(new(CommandKind.PhysicalAction,grazer,Text:"collect"));Until(()=>w.Physical.Products>0,12000,"grazer products");
  long second=w.Physical.Animals.Keys.First(id=>id!=grazer);w.Find(second)!.X=w.Find(grazer)!.X+1;w.Find(second)!.Y=w.Find(grazer)!.Y;w.Physical.Animals[second].Tame=true;w.Physical.Animals[second].Nutrition=100;w.Physical.Animals[grazer].Nutrition=100;w.Physical.Animals[grazer].NextBirth=w.Tick;Until(()=>w.Physical.Births>0,600,"healthy reproduction");
  var a=w.Physical.Animals[grazer];a.Nutrition=0;Command(new(CommandKind.PhysicalAction,grazer,Text:"feed"));Until(()=>a.Nutrition>=35,12000,"physical feed");Require(w.Physical.Animals.Count<=16,"Ecology exceeded local budget.");SaveStore.Write(Path.Combine(output,"manufacturing-husbandry.lastlight"),w,new ViewState{CameraX=64,CameraY=64,OpenTab="Engineering"},d);Console.WriteLine("PASS F05: grain taming/feed, training improves fiber yield, nutrition-gated birth and bounded ecology");
 }
}
